34	\centering
35	\caption{监督学习与无监督学习的对比}
36	\begin{tabular}{lll}
37	\toprule
38	\textbf{维度} & \textbf{监督学习} & \textbf{无监督学习} \\
39	\midrule
40	数据 & $(x, y)$，$x$ 为数据，$y$ 为标签 & 仅有 $x$，无标签 \\
41	目标 & 学习 $x \to y$ 的映射函数 & 发现数据的隐藏/底层结构 \\
42	典型任务 & 分类、回归、目标检测 & 聚类、特征提取、降维 \\
43	\bottomrule
44	\end{tabular}
45	\end{table}
